interface BrandLogoProps {
  system: DesignSystemType;
  size?: number;
}

/**
 * Renders the official brand logo for each design system.
 * Uses react-native Image for PNG assets and react-native-svg SvgXml for SVG assets.
 */
const BrandLogo: React.FC<BrandLogoProps> = ({ system, size = 28 }) => {
  switch (system) {
    case 'expo':
      // Expo logo is a real PNG – use Image
      return (
        <View style={{ width: size, height: size, flexShrink: 0, marginRight: 10 }}>
          <Image
            source={expoLogoPng}
            style={{ width: size, height: size, borderRadius: 7 }}
            resizeMode="contain"
          />
        </View>
      );

    case 'tamagui':
      return (
        <SvgXml xml={tamaguiLogoSvg} width={size} height={size} style={{ flexShrink: 0, marginRight: 10 }} />
      );

    case 'ant':
      return (
        <SvgXml xml={antDesignLogoSvg} width={size} height={size} style={{ flexShrink: 0, marginRight: 10 }} />
      );

    case 'native':
      return (
        <SvgXml xml={rnLogoSvg} width={size} height={size} style={{ flexShrink: 0, marginRight: 10 }} />
      );

    case 'paper':
      return (
        <SvgXml xml={paperLogoSvg} width={size} height={size} style={{ flexShrink: 0, marginRight: 10 }} />
      );

    case 'googlemd3web':
      return (
        <SvgXml xml={materialLogoSvg} width={size} height={size} style={{ flexShrink: 0, marginRight: 10 }} />
      );

    default:
      return <View style={{ width: size, height: size, flexShrink: 0, marginRight: 10 }} />;
  }
};

export default BrandLogo;
